.sl-category-typo.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-category-typo .sl-text-primary { color: var(--smartlearn-primary); }
.sl-category-typo .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-category-typo .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-category-typo .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-category-typo .sl-border { border-color: var(--smartlearn-card-border); }
.sl-category-typo h2, .sl-category-typo h3 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-category-typo .sl-tracking-wide { letter-spacing: 0.1em; }
.sl-category-typo .sl-typo-title,
.sl-category-typo .sl-typo-num,
.sl-category-typo .sl-typo-icon { transition: opacity 0.25s ease, transform 0.25s ease, color 0.25s ease; }
.sl-category-typo .sl-typo-icon { opacity: 0; transform: translateX(-16px); }
[dir="rtl"] .sl-category-typo .sl-typo-icon { transform: translateX(16px); }
[dir="rtl"] .sl-category-typo .fa-arrow-right { transform: scaleX(-1); }
.sl-category-typo .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 4px;
}
.sl-category-typo .sl-typo-item:focus-within .sl-typo-icon {
    opacity: 1;
    transform: translateX(0);
}
[dir="rtl"] .sl-category-typo .sl-typo-item:focus-within .fa-arrow-right { transform: scaleX(-1); }
.sl-category-typo .sl-typo-preview {
    width: 400px;
    height: 300px;
    top: 0;
    left: 0;
    opacity: 0;
    transition: opacity 0.25s ease;
    border-radius: var(--smartlearn-radius, 1rem);
    overflow: hidden;
    box-shadow: 0 2rem 4rem rgba(0, 0, 0, 0.2);
}
.sl-category-typo .sl-typo-scrim {
    background-color: rgba(0, 0, 0, 0.35);
    background-color: color-mix(in oklab, var(--smartlearn-bg) 52%, transparent);
}
@media (hover: hover) and (min-width: 992px) {
    .sl-category-typo .sl-typo-list:hover .sl-typo-title,
    .sl-category-typo .sl-typo-list:hover .sl-typo-num { opacity: 0.3; }
    .sl-category-typo .sl-typo-item:hover .sl-typo-title {
        opacity: 1;
        transform: translateX(20px);
        color: var(--smartlearn-primary);
    }
    [dir="rtl"] .sl-category-typo .sl-typo-item:hover .sl-typo-title { transform: translateX(-20px); }
    .sl-category-typo .sl-typo-item:hover .sl-typo-num {
        opacity: 1;
        color: var(--smartlearn-primary);
    }
    .sl-category-typo .sl-typo-item:hover .sl-typo-icon {
        opacity: 1;
        transform: translateX(0);
    }
}
@media (max-width: 991.98px) {
    .sl-category-typo .sl-typo-icon { opacity: 1; transform: translateX(0); }
}
@media (prefers-reduced-motion: reduce) {
    .sl-category-typo .sl-typo-title,
    .sl-category-typo .sl-typo-num,
    .sl-category-typo .sl-typo-icon,
    .sl-category-typo .sl-typo-preview { transition: none; }
    .sl-category-typo .sl-typo-item:hover .sl-typo-title { transform: none; }
}
@media (min-width: 992px) {
    .sl-category-typo { padding-top: 6rem !important; padding-bottom: 6rem !important; }
}

