(function() {
    const init = () => {
        document.querySelectorAll('.sl-category-typo').forEach((section) => {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';

            const items = section.querySelectorAll('.sl-typo-item');
            const preview = section.querySelector('.sl-typo-preview');
            const previewImg = preview ? preview.querySelector('.sl-typo-preview-img') : null;
            if (!items.length || !preview || !previewImg) return;

            let rafId = null;
            let active = false;
            let currentX = 0;
            let currentY = 0;
            let aimX = 0;
            let aimY = 0;

            const canAnimate = () =>
                window.matchMedia('(min-width: 992px)').matches &&
                window.matchMedia('(hover: hover)').matches &&
                !window.matchMedia('(prefers-reduced-motion: reduce)').matches;

            const stopLoop = () => {
                active = false;
                if (rafId !== null) {
                    cancelAnimationFrame(rafId);
                    rafId = null;
                }
                preview.style.opacity = '0';
            };

            const tick = () => {
                if (!active) return;
                currentX += (aimX - currentX) * 0.14;
                currentY += (aimY - currentY) * 0.14;
                preview.style.transform = `translate3d(${currentX - 200}px, ${currentY - 150}px, 0)`;
                rafId = requestAnimationFrame(tick);
            };

            section.addEventListener('mousemove', (e) => {
                if (!canAnimate()) return;
                const rect = section.getBoundingClientRect();
                aimX = e.clientX - rect.left;
                aimY = e.clientY - rect.top;
            });

            items.forEach((item) => {
                item.addEventListener('mouseenter', (e) => {
                    if (!canAnimate()) return;
                    const srcImg = item.querySelector('.sl-typo-src-img');
                    const src = srcImg ? srcImg.getAttribute('src') : '';
                    if (!src) return;
                    const rect = section.getBoundingClientRect();
                    aimX = e.clientX - rect.left;
                    aimY = e.clientY - rect.top;
                    if (!active) {
                        currentX = aimX;
                        currentY = aimY;
                        preview.style.transform = `translate3d(${currentX - 200}px, ${currentY - 150}px, 0)`;
                    }
                    if (previewImg.getAttribute('src') !== src) {
                        previewImg.setAttribute('src', src);
                    }
                    active = true;
                    preview.style.opacity = '1';
                    if (rafId === null) {
                        rafId = requestAnimationFrame(tick);
                    }
                });

                item.addEventListener('mouseleave', () => {
                    stopLoop();
                });
            });

            section.addEventListener('mouseleave', stopLoop);
        });
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
